ISS=['환율·해외투자','금리·대출','물가·생활비','부동산·대출규제','이번 주 시장 정리']
off=int(sys.argv[1]) if len(sys.argv)>1 else 1
d=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=9))).date()+datetime.timedelta(days=off)
d=d-datetime.timedelta(days=d.weekday())
y,w,_=d.isocalendar(); r=random.Random(y*100+w)
slots=['검색형','검색형','검색형','이슈형','이슈형','이슈형']; r.shuffle(slots)
iss=ISS[:]; r.shuffle(iss)
k=((d-datetime.date(2026,10,12)).days//7)*3
ev=[(KW[(k+i)%len(KW)],(k+i)%len(KW)+1) for i in range(3)]
for i,s in enumerate(slots):
    day=d+datetime.timedelta(days=i)
    if s=='검색형': t,n=ev.pop(0); print('월화수목금토'[i],day,s,f'[영차 금융세미나 #{n}]',t)
    else: print('월화수목금토'[i],day,s,iss.pop(0))
